import{_ as a,o,c as s,b6 as n}from"./chunks/framework.BUXTSoD9.js";const m=JSON.parse('{"title":"Disena paginas y botones siguiendo guias de diseno de UI","description":"","frontmatter":{},"headers":[],"relativePath":"es-es/stage-2/frontend/multi-product-ui/index.md","filePath":"es-es/stage-2/frontend/multi-product-ui/index.md"}'),i={name:"es-es/stage-2/frontend/multi-product-ui/index.md"};function t(l,e,r,d,p,c){return o(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="disena-paginas-y-botones-siguiendo-guias-de-diseno-de-ui" tabindex="-1">Disena paginas y botones siguiendo guias de diseno de UI <a class="header-anchor" href="#disena-paginas-y-botones-siguiendo-guias-de-diseno-de-ui" aria-label="Permalink to “Disena paginas y botones siguiendo guias de diseno de UI”">​</a></h1><p>Muchas personas dicen &quot;quiero que mi pagina se parezca mas a la de Apple&quot; o &quot;quiero que los botones se vean mas sofisticados&quot;, pero cuando realmente empiezan a trabajar, a menudo se quedan atascados en una pregunta:</p><p><strong>Exactamente, que debo tomar como referencia?</strong></p><p>Mirar capturas de pantalla e imitar solo te ensena si algo &quot;se parece o no&quot;. Pero cuando abres las guias de diseno de Apple, Google, Microsoft y Atlassian, descubres que lo realmente impresionante no es el estilo visual, sino que <strong>explican claramente los problemas de diseno</strong>: que destacar primero en una pagina, como jerarquizar los botones, como enfatizar las operaciones - estos criterios de juicio son lo esencial.</p><blockquote><p>Seguir guias de diseno no se trata de hacer que algo &quot;se parezca a alguien&quot;, sino de aprender como otros toman decisiones.</p></blockquote><div class="info custom-block"><p class="custom-block-title">Por que aprender esto ahora</p><p>Las reglas de diseno ya han sido entrenadas en los modelos, absorbidas por defecto en las herramientas de diseno, e incluso con solo pegar algunas capturas de pantalla la IA puede aprenderlas. Pero aun necesitamos saber de donde vienen estas reglas y por que se definen asi.</p></div><h2 id="primero-mira-algunos-textos-originales-y-siente-la-diferencia" tabindex="-1">Primero mira algunos textos originales y siente la diferencia <a class="header-anchor" href="#primero-mira-algunos-textos-originales-y-siente-la-diferencia" aria-label="Permalink to “Primero mira algunos textos originales y siente la diferencia”">​</a></h2><p>Si antes pensabas que &quot;las guias de diseno solo hablan de estilo&quot;, primero mira algunas citas oficiales.</p><p>Normalmente en un equipo solemos decir cosas como:</p><ul><li>Haz un dropdown</li><li>Pon un menu aqui</li><li>Agrega algunas funciones a la barra de menu</li><li>Pon dos botones aqui, uno de confirmar y otro de cancelar</li></ul><p>Parece que no hay problema, pero en las guias de las grandes empresas, estos terminos no son conceptos vagos, sino que estan desglosados con mucho detalle.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Lo que solemos decir casualmente</th><th style="text-align:left;">Texto oficial</th><th style="text-align:left;">En pocas palabras</th></tr></thead><tbody><tr><td style="text-align:left;">&quot;Haz un menu&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">&quot;A menu reveals its options...&quot;</a></td><td style="text-align:left;"><code>Menu</code> se usa para realizar acciones</td></tr><tr><td style="text-align:left;">&quot;Pon funciones en la barra de menu&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">&quot;menu bar menus contain all the commands...&quot;</a></td><td style="text-align:left;">Este es el menu de comandos en la parte superior de la aplicacion</td></tr><tr><td style="text-align:left;">&quot;Haz un dropdown&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">&quot;A pop-up list lets the user choose one option among several.&quot;</a></td><td style="text-align:left;"><code>pop-up</code> es para seleccionar uno de una lista</td></tr><tr><td style="text-align:left;">&quot;Tambien haz un dropdown&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">&quot;A pull-down list is generally used for selecting commands in a specific context.&quot;</a></td><td style="text-align:left;"><code>pull-down</code> es para abrir y realizar la accion actual</td></tr><tr><td style="text-align:left;">&quot;El menu tambien sirve para filtrar?&quot;</td><td style="text-align:left;">Fluent: <a href="https://fluent2.microsoft.design/components/web/react/core/menu/usage" target="_blank" rel="noreferrer">&quot;If you need to collect information from people, try a select, dropdown, or combobox instead.&quot;</a></td><td style="text-align:left;"><code>Menu</code> no es para seleccionar valores</td></tr><tr><td style="text-align:left;">&quot;El menu tambien sirve como navegacion?&quot;</td><td style="text-align:left;">Material: <a href="https://m1.material.io/components/menus.html" target="_blank" rel="noreferrer">&quot;Menus should not be used as a primary method for navigation within an app.&quot;</a></td><td style="text-align:left;"><code>Menu</code> no es navegacion principal</td></tr><tr><td style="text-align:left;">&quot;Escribe OK / Cancel en los botones&quot;</td><td style="text-align:left;">Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/alerts" target="_blank" rel="noreferrer">&quot;Always use &#39;Cancel&#39; to title a button that cancels the alert&#39;s action.&quot;</a></td><td style="text-align:left;">El texto de los botones no se puede escribir de cualquier forma</td></tr></tbody></table><blockquote><p>Las citas de la tabla se pueden hacer clic directamente para ir a la pagina oficial correspondiente.</p></blockquote><p>Esta es la parte que mas impacta cuando lees realmente las guias de diseno por primera vez:</p><blockquote><p>Lo que normalmente pensamos que es discutir de UI, en realidad muchas veces es solo comunicarnos con un monton de palabras vagas.</p></blockquote><p>Apple no se limita a decir &quot;haz un menu&quot;; continua distinguiendo:</p><ul><li><code>menu</code></li><li><code>menu bar menu</code></li><li><code>pop-up button</code></li><li><code>pull-down button</code></li><li><code>context menu</code></li></ul><p>Fluent no se limita a decir &quot;dropdown&quot;; continua distinguiendo:</p><ul><li><code>menu</code></li><li><code>dropdown</code></li><li><code>select</code></li><li><code>combobox</code></li></ul><p>Esta es la necesidad de las guias de diseno.</p><p>No es para hacer que las paginas parezcan mas profesionales, sino para que cuando el equipo discuta sobre UI, cada persona no tenga cosas diferentes en mente.</p><h2 id="lo-que-aprenderas" tabindex="-1">Lo que aprenderas <a class="header-anchor" href="#lo-que-aprenderas" aria-label="Permalink to “Lo que aprenderas”">​</a></h2><ol><li>Por que debes consultar las guias de diseno al disenar paginas y botones</li><li>Que contenido de las guias de Apple, Material, Fluent y Atlassian es mas valioso consultar</li><li>Como disenar claramente la &quot;jerarquia de paginas&quot; y la &quot;jerarquia de botones&quot;</li><li>Como hacer que la IA consulte las guias de otros para generar paginas y botones</li></ol><h2 id="_1-por-que-las-guias-de-diseno-te-ayudan-a-disenar-paginas-con-claridad" tabindex="-1">1. Por que las guias de diseno te ayudan a disenar paginas con claridad <a class="header-anchor" href="#_1-por-que-las-guias-de-diseno-te-ayudan-a-disenar-paginas-con-claridad" aria-label="Permalink to “1. Por que las guias de diseno te ayudan a disenar paginas con claridad”">​</a></h2><p>Despues de leer los textos originales anteriores, descubriras un punto clave:</p><p><strong>Las guias de diseno no son un complemento estetico, sino que primero precisan el vocabulario.</strong></p><p>Muchas paginas no se ven bien no porque la combinacion de colores no sea sofisticada, sino porque la jerarquia de informacion es confusa.</p><p>Muchos botones no son faciles de usar no porque los bordes redondeados esten mal, sino porque:</p><ul><li>Hay demasiados botones principales, el usuario no sabe cual presionar</li><li>Los botones de peligro se ven igual que los botones normales</li><li>Todos los botones de la pagina compiten por la atencion</li><li>El estilo y la semantica de los botones son inconsistentes entre paginas</li></ul><p>Las guias de diseno maduras abordan precisamente estos problemas. Normalmente definen:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Contenido de la guia</th><th style="text-align:left;">Que problema resuelve</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Jerarquia de pagina</strong></td><td style="text-align:left;">Donde mirar primero, donde mirar despues, como organizar la informacion</td></tr><tr><td style="text-align:left;"><strong>Fundamentos visuales</strong></td><td style="text-align:left;">Como unificar colores, espaciado, tipografia, bordes redondeados, sombras</td></tr><tr><td style="text-align:left;"><strong>Jerarquia de botones</strong></td><td style="text-align:left;">Como distinguir boton principal, secundario, de texto, de peligro</td></tr><tr><td style="text-align:left;"><strong>Reglas de estado</strong></td><td style="text-align:left;">Como se ven hover, focus, disabled, loading</td></tr><tr><td style="text-align:left;"><strong>Semantica de interaccion</strong></td><td style="text-align:left;">Que boton es &quot;confirmar&quot;, cual es &quot;cancelar&quot;, cual es &quot;mas acciones&quot;</td></tr></tbody></table><p>Por lo tanto, lo que realmente proporcionan las guias de diseno no es un &quot;aspecto&quot;, sino un <strong>conjunto de criterios de juicio</strong>.</p><h2 id="_2-al-consultar-las-guias-de-grandes-empresas-en-que-debes-enfocarte" tabindex="-1">2. Al consultar las guias de grandes empresas, en que debes enfocarte <a class="header-anchor" href="#_2-al-consultar-las-guias-de-grandes-empresas-en-que-debes-enfocarte" aria-label="Permalink to “2. Al consultar las guias de grandes empresas, en que debes enfocarte”">​</a></h2><h3 id="_2-1-consultar-apple-aprender-a-definir-con-suficiente-detalle" tabindex="-1">2.1 Consultar Apple: Aprender a &quot;definir con suficiente detalle&quot; <a class="header-anchor" href="#_2-1-consultar-apple-aprender-a-definir-con-suficiente-detalle" aria-label="Permalink to “2.1 Consultar Apple: Aprender a &quot;definir con suficiente detalle&quot;”">​</a></h3><p>Lo mas valioso de Apple no es solo la contencion visual, sino que define los conceptos con mucho detalle.</p><p>Lo que muchos equipos llaman &quot;menu&quot; o &quot;dropdown&quot;, Apple continua desglosando:</p><ul><li><code>menu</code>: un conjunto de comandos, opciones o estados</li><li><code>menu bar menu</code>: coleccion de comandos a nivel de aplicacion</li><li><code>pop-up button</code>: seleccionar un valor</li><li><code>pull-down button</code>: activar comandos en el contexto actual</li><li><code>context menu</code>: acciones comunes relacionadas con el objeto o tarea actual</li></ul><p>Esta distincion es muy importante porque afecta directamente:</p><ul><li>Si este componente es para seleccionar valores o para realizar acciones</li><li>Si pertenece a una seccion de la pagina o a nivel de aplicacion</li><li>Si debe mostrar persistentemente el valor seleccionado o solo expandir comandos temporalmente</li></ul><p>Cuando empiezas a pensar con este nivel de granularidad, las paginas que disenes seran mucho mas claras.</p><h3 id="_2-2-consultar-apple-aprender-jerarquia-de-paginas-y-contencion" tabindex="-1">2.2 Consultar Apple: Aprender jerarquia de paginas y contencion <a class="header-anchor" href="#_2-2-consultar-apple-aprender-jerarquia-de-paginas-y-contencion" aria-label="Permalink to “2.2 Consultar Apple: Aprender jerarquia de paginas y contencion”">​</a></h3><p>Las Apple Human Interface Guidelines son especialmente adecuadas para aprender dos cosas:</p><ul><li>Como establecer una jerarquia clara en las paginas</li><li>Como mantener los controles claros sin que acaparen la atencion</li></ul><p>Apple enfatiza <code>Hierarchy</code>, <code>Harmony</code>, <code>Consistency</code>. Esto significa que al disenar paginas debes responder:</p><ul><li>Cual es la informacion mas importante de la pagina actual</li><li>Cual es la tarea principal del usuario</li><li>Que operacion debe ser mas visible y cual debe retroceder</li></ul><p>Si consultas a Apple para disenar paginas, puedes enfocarte en:</p><ul><li>No fragmentar demasiado la informacion del primer vistazo, enfocarse primero en el contenido central</li><li>Usar espacios en blanco, tamano de fuente y agrupacion para crear orden, en lugar de apilar muchos bordes</li><li>No hacer que todos los botones tengan alto enfasis, solo las acciones clave deben ser las mas prominentes</li></ul><h3 id="_2-3-consultar-material-aprender-estructura-clara-de-paginas" tabindex="-1">2.3 Consultar Material: Aprender estructura clara de paginas <a class="header-anchor" href="#_2-3-consultar-material-aprender-estructura-clara-de-paginas" aria-label="Permalink to “2.3 Consultar Material: Aprender estructura clara de paginas”">​</a></h3><p>Material Design es muy adecuado para aprender &quot;como las paginas organizan los flujos de tareas&quot;.</p><p>Muchos de sus componentes y guias de layout tienen como nucleo ayudarte a aclarar:</p><ul><li>Si la pagina es de navegacion o de ejecucion de tareas</li><li>Si la pagina actual es para que el usuario lea, seleccione o envie</li><li>Que elementos de una pagina deben repetirse de forma estable y cuales deben responder a cambios de contexto</li></ul><p>Si consultas Material para disenar paginas, puedes enfocarte en:</p><ul><li>Secciones de pagina claras, responsabilidades de modulos bien definidas</li><li>Navegacion, area de contenido y area de operaciones con division clara del trabajo</li><li>Diferentes estilos de botones corresponden a diferentes prioridades de operacion</li></ul><h3 id="_2-4-consultar-fluent-aprender-limites-de-componentes-y-jerarquia-de-botones" tabindex="-1">2.4 Consultar Fluent: Aprender limites de componentes y jerarquia de botones <a class="header-anchor" href="#_2-4-consultar-fluent-aprender-limites-de-componentes-y-jerarquia-de-botones" aria-label="Permalink to “2.4 Consultar Fluent: Aprender limites de componentes y jerarquia de botones”">​</a></h3><p>Fluent 2 es muy adecuado para productos de backend, herramientas y sistemas de formularios complejos. Lo mas valioso que tiene es que te dice directamente &quot;no mezcles conceptos&quot;.</p><p>Por ejemplo, dice explicitamente: si necesitas &quot;collect information&quot;, no sigas usando <code>menu</code>, sino que deberias considerar <code>select</code>, <code>dropdown</code>, <code>combobox</code>.</p><p>Esta frase es muy importante porque rompe la idea de &quot;todo es mas o menos lo mismo&quot; que mucha gente tiene en mente.</p><p>Fluent 2 tambien valora mucho:</p><ul><li>Jerarquia de operaciones</li><li>Limites semanticos de componentes</li><li>Claridad en escenarios de informacion densa</li></ul><p>Si consultas Fluent para disenar botones, puedes enfocarte en:</p><ul><li><code>Primary button</code> para la accion mas importante del area actual</li><li><code>Secondary button</code> para acciones de soporte</li><li>Botones de enfasis debil como <code>Subtle</code>, <code>Transparent</code> para operaciones que no deben interrumpir el flujo principal</li><li>Cuantos mas botones haya en la pagina, mas debes controlar la prioridad visual</li></ul><h3 id="_2-5-consultar-atlassian-aprender-a-gestionar-paginas-y-botones-de-forma-sistematica" tabindex="-1">2.5 Consultar Atlassian: Aprender a gestionar paginas y botones de forma sistematica <a class="header-anchor" href="#_2-5-consultar-atlassian-aprender-a-gestionar-paginas-y-botones-de-forma-sistematica" aria-label="Permalink to “2.5 Consultar Atlassian: Aprender a gestionar paginas y botones de forma sistematica”">​</a></h3><p>El Atlassian Design System es especialmente adecuado para situaciones donde &quot;un equipo hace muchas paginas&quot;. Enfatiza:</p><ul><li>Los foundations son la base compartida</li><li>Los tokens son el metodo para unificar las decisiones visuales</li><li>Los components son los bloques de interaccion que se reutilizan repetidamente</li></ul><p>Si consultas Atlassian para hacer paginas y botones, lo mas valioso es:</p><ul><li>Convertir el tamano, color, bordes redondeados y espaciado de los botones en reglas unificadas</li><li>Fijar el ritmo del layout de pagina</li><li>Hacer que diferentes paginas, aunque tengan contenido diferente, compartan un lenguaje estructural consistente</li></ul><h2 id="_3-al-disenar-paginas-que-puntos-de-la-guia-debes-consultar" tabindex="-1">3. Al disenar paginas, que puntos de la guia debes consultar <a class="header-anchor" href="#_3-al-disenar-paginas-que-puntos-de-la-guia-debes-consultar" aria-label="Permalink to “3. Al disenar paginas, que puntos de la guia debes consultar”">​</a></h2><p>Cuando mires un sistema de diseno, no preguntes primero &quot;esta pagina se ve bien o no&quot;, sino que primero te hagas las siguientes preguntas.</p><h3 id="_3-1-primer-vistazo-a-la-pagina-es-clara-la-jerarquia-principal-secundaria" tabindex="-1">3.1 Primer vistazo a la pagina, es clara la jerarquia principal/secundaria <a class="header-anchor" href="#_3-1-primer-vistazo-a-la-pagina-es-clara-la-jerarquia-principal-secundaria" aria-label="Permalink to “3.1 Primer vistazo a la pagina, es clara la jerarquia principal/secundaria”">​</a></h3><p>Una pagina generalmente debe tener al menos tres niveles:</p><ul><li><strong>Informacion principal</strong>: el contenido mas importante de la pagina actual</li><li><strong>Informacion auxiliar</strong>: contenido que ayuda a comprender o complementar</li><li><strong>Operaciones secundarias</strong>: acciones que no deben interferir con la tarea principal</li></ul><p>Si los tres niveles no estan diferenciados, la pagina sera &quot;todo es importante&quot;, lo que equivale a &quot;nada es importante&quot;.</p><h3 id="_3-2-el-layout-de-la-pagina-sirve-a-la-tarea-o-solo-apila-modulos" tabindex="-1">3.2 El layout de la pagina, sirve a la tarea o solo apila modulos <a class="header-anchor" href="#_3-2-el-layout-de-la-pagina-sirve-a-la-tarea-o-solo-apila-modulos" aria-label="Permalink to “3.2 El layout de la pagina, sirve a la tarea o solo apila modulos”">​</a></h3><p>Al consultar las guias, presta especial atencion a:</p><ul><li>Si el area de titulo aclara el objetivo de la pagina</li><li>Si el area de contenido principal esta organizada alrededor de la tarea</li><li>Si los botones de operacion estan cerca del contenido relacionado</li><li>Si la informacion secundaria esta debilmente enfatizada</li></ul><h3 id="_3-3-las-operaciones-de-la-pagina-tienen-prioridad" tabindex="-1">3.3 Las operaciones de la pagina, tienen prioridad <a class="header-anchor" href="#_3-3-las-operaciones-de-la-pagina-tienen-prioridad" aria-label="Permalink to “3.3 Las operaciones de la pagina, tienen prioridad”">​</a></h3><p>Muchas paginas a primera vista tienen 6 botones, y cada boton parece un CTA, esta es una tipica perdida de jerarquia.</p><p>Un enfoque mas razonable seria:</p><ul><li>Un area generalmente tiene solo una accion principal</li><li>Las acciones secundarias pueden usar bordes, botones de texto o estilos mas debiles</li><li>Las acciones de riesgo no deben verse igual que la accion principal</li></ul><h2 id="_4-al-disenar-botones-que-puntos-de-la-guia-debes-consultar" tabindex="-1">4. Al disenar botones, que puntos de la guia debes consultar <a class="header-anchor" href="#_4-al-disenar-botones-que-puntos-de-la-guia-debes-consultar" aria-label="Permalink to “4. Al disenar botones, que puntos de la guia debes consultar”">​</a></h2><p>Los botones son la parte mas facil de &quot;disenar de cualquier manera&quot;, pero tambien la que mas puede revelar si un sistema es maduro.</p><h3 id="_4-1-primero-separa-los-botones-por-semantica-luego-por-estilo" tabindex="-1">4.1 Primero separa los botones por &quot;semantica&quot;, luego por &quot;estilo&quot; <a class="header-anchor" href="#_4-1-primero-separa-los-botones-por-semantica-luego-por-estilo" aria-label="Permalink to “4.1 Primero separa los botones por &quot;semantica&quot;, luego por &quot;estilo&quot;”">​</a></h3><p>No pienses primero en &quot;boton azul o boton negro&quot;, primero piensa en que rol tiene este boton.</p><p>Los roles comunes de botones se pueden clasificar asi:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Tipo de boton</th><th style="text-align:left;">Funcion</th><th style="text-align:left;">Estrategia de estilo comun</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Primary</strong></td><td style="text-align:left;">La accion mas critica del area actual</td><td style="text-align:left;">Solido, alto contraste, el mas visible</td></tr><tr><td style="text-align:left;"><strong>Secondary</strong></td><td style="text-align:left;">Acciones de soporte</td><td style="text-align:left;">Borde o un nivel de enfasis menor</td></tr><tr><td style="text-align:left;"><strong>Tertiary / Text</strong></td><td style="text-align:left;">Operaciones debiles</td><td style="text-align:left;">Texto o baja proporcion visual</td></tr><tr><td style="text-align:left;"><strong>Destructive</strong></td><td style="text-align:left;">Eliminar, desactivar, limpiar y otras operaciones de riesgo</td><td style="text-align:left;">Color de advertencia o estilo de riesgo explicito</td></tr><tr><td style="text-align:left;"><strong>Icon button</strong></td><td style="text-align:left;">Operaciones de herramienta locales</td><td style="text-align:left;">Simple, cerca del contexto</td></tr></tbody></table><h3 id="_4-2-una-pagina-no-debe-tener-demasiados-primary-buttons" tabindex="-1">4.2 Una pagina no debe tener demasiados Primary Buttons <a class="header-anchor" href="#_4-2-una-pagina-no-debe-tener-demasiados-primary-buttons" aria-label="Permalink to “4.2 Una pagina no debe tener demasiados Primary Buttons”">​</a></h3><p>Este es el error en el que mas caen los principiantes.</p><p>Si hay 4 botones principales en la pagina, entonces es como si no hubiera boton principal. El significado del boton principal es &quot;decir al usuario que es lo que mas deberia hacer ahora&quot;.</p><p>Puedes seguir la practica comun de muchos sistemas de diseno:</p><ul><li>Un area principal generalmente conserva solo un boton principal</li><li>Cancelar, volver, cerrar generalmente no compiten al mismo nivel que el boton de confirmacion</li><li>Mas operaciones se colocan en botones secundarios o menus</li></ul><h3 id="_4-3-los-botones-deben-poder-expresar-cambios-de-estado" tabindex="-1">4.3 Los botones deben poder expresar cambios de estado <a class="header-anchor" href="#_4-3-los-botones-deben-poder-expresar-cambios-de-estado" aria-label="Permalink to “4.3 Los botones deben poder expresar cambios de estado”">​</a></h3><p>Las guias de diseno generalmente describen los estados de los botones con mucho detalle:</p><ul><li>Estado por defecto</li><li>Estado hover</li><li>Estado focus</li><li>Estado disabled</li><li>Estado loading</li><li>Estado de peligro</li></ul><p>Esto es importante porque un boton no es una imagen estatica, sino uno de los controles que mas se activan durante la operacion del usuario.</p><h3 id="_4-4-el-texto-de-los-botones-tambien-es-parte-del-diseno" tabindex="-1">4.4 El texto de los botones tambien es parte del diseno <a class="header-anchor" href="#_4-4-el-texto-de-los-botones-tambien-es-parte-del-diseno" aria-label="Permalink to “4.4 El texto de los botones tambien es parte del diseno”">​</a></h3><p>El texto del boton no es solo un &quot;problema de redaccion&quot;, afecta directamente la comprension del usuario.</p><p>Por ejemplo:</p><ul><li><code>Guardar</code></li><li><code>Guardar cambios</code></li><li><code>Publicar ahora</code></li><li><code>Eliminar proyecto</code></li><li><code>Mover a la papelera</code></li></ul><p>Estos textos transmiten expectativas psicologicas completamente diferentes. Las guias maduras generalmente requieren que las etiquetas de los botones expresen claramente la accion, en lugar de usar palabras vagas.</p><h2 id="_5-una-lista-de-verificacion-muy-practica-para-el-diseno-de-paginas-y-botones" tabindex="-1">5. Una lista de verificacion muy practica para el diseno de paginas y botones <a class="header-anchor" href="#_5-una-lista-de-verificacion-muy-practica-para-el-diseno-de-paginas-y-botones" aria-label="Permalink to “5. Una lista de verificacion muy practica para el diseno de paginas y botones”">​</a></h2><p>Cuando disenes paginas tu mismo, puedes revisar rapidamente esta lista:</p><h3 id="lista-de-paginas" tabindex="-1">Lista de paginas <a class="header-anchor" href="#lista-de-paginas" aria-label="Permalink to “Lista de paginas”">​</a></h3><ul><li>El titulo de la pagina explica claramente la tarea actual</li><li>La informacion mas importante del primer vistazo es visible de inmediato</li><li>La pagina esta organizada por flujo de tareas, no por lo que se te ocurre poner</li><li>Solo hay una accion principal en la misma area</li><li>El contenido secundario esta debilmente enfatizado</li></ul><h3 id="lista-de-botones" tabindex="-1">Lista de botones <a class="header-anchor" href="#lista-de-botones" aria-label="Permalink to “Lista de botones”">​</a></h3><ul><li>Este boton es una accion principal o secundaria</li><li>Por que merece ser mas visible que otros botones</li><li>Hay demasiados botones principales en la pagina</li><li>Las operaciones de peligro estan claramente identificadas</li><li>El texto del boton es suficientemente especifico</li></ul><h2 id="_6-como-usar-ia-consultando-las-guias-de-otros-para-disenar-paginas" tabindex="-1">6. Como usar IA consultando las guias de otros para disenar paginas <a class="header-anchor" href="#_6-como-usar-ia-consultando-las-guias-de-otros-para-disenar-paginas" aria-label="Permalink to “6. Como usar IA consultando las guias de otros para disenar paginas”">​</a></h2><p>Esta seccion es la mas practica.</p><p>Muchas personas cuando piden a la IA que disene paginas, solo dicen:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Hazme una pagina de configuracion, que se vea mas sofisticada, estilo Apple</span></span></code></pre></div><p>Este tipo de prompt es demasiado vago, la IA generalmente solo puede imitar &quot;fondo blanco, bordes redondeados, sombras&quot;.</p><p>Para principiantes, un enfoque mas practico no es resumir un gran parrafo uno mismo, sino directamente pegar a la IA <strong>las frases clave del texto original de la guia</strong>.</p><p>Esto tiene dos ventajas:</p><ul><li>No necesitas &quot;traducir&quot; tu mismo el pensamiento de diseno</li><li>La IA puede mas facilmente entender paginas y botones segun las definiciones oficiales</li></ul><h3 id="_6-1-ejemplo-1-hacer-que-la-ia-consulte-apple-para-disenar-una-pagina-de-configuracion" tabindex="-1">6.1 Ejemplo 1: Hacer que la IA consulte Apple para disenar una pagina de configuracion <a class="header-anchor" href="#_6-1-ejemplo-1-hacer-que-la-ia-consulte-apple-para-disenar-una-pagina-de-configuracion" aria-label="Permalink to “6.1 Ejemplo 1: Hacer que la IA consulte Apple para disenar una pagina de configuracion”">​</a></h3><p>Primero busca una frase del texto original de Apple:</p><blockquote><p><a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">&quot;Establish a clear visual hierarchy...&quot;</a></p></blockquote><p>Puedes pegarlo directamente a la IA asi:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Consulta esta frase de las Apple Human Interface Guidelines:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;Establish a clear visual hierarchy...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Ayudame a disenar una pagina de configuracion de seguridad de cuenta.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Requiere jerarquia de pagina clara, informacion importante primero, agrupacion ordenada.</span></span></code></pre></div><p>El punto clave de escribirlo asi: no necesitas explicar demasiado tu mismo, solo pega las palabras originales de Apple.</p><h3 id="_6-2-ejemplo-2-hacer-que-la-ia-consulte-fluent-para-disenar-botones-de-pagina-de-backend" tabindex="-1">6.2 Ejemplo 2: Hacer que la IA consulte Fluent para disenar botones de pagina de backend <a class="header-anchor" href="#_6-2-ejemplo-2-hacer-que-la-ia-consulte-fluent-para-disenar-botones-de-pagina-de-backend" aria-label="Permalink to “6.2 Ejemplo 2: Hacer que la IA consulte Fluent para disenar botones de pagina de backend”">​</a></h3><p>Primero busca una frase del texto original de Fluent:</p><blockquote><p><a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">&quot;Only use one primary button in a layout...&quot;</a></p></blockquote><p>Puedes pegarlo directamente a la IA asi:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Consulta esta frase de Fluent 2:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;Only use one primary button in a layout...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Ayudame a disenar los botones de un backend de gestion de equipos.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">El boton de agregar miembro debe ser el mas visible, exportar, filtrar, mas operaciones mas debiles, el boton de eliminar destacado por separado.</span></span></code></pre></div><p>Esta frase es especialmente adecuada para principiantes porque le dice directamente a la IA: no pongas demasiados botones principales en un area.</p><h3 id="_6-3-ejemplo-3-hacer-que-la-ia-consulte-simultaneamente-las-guias-de-pagina-y-botones" tabindex="-1">6.3 Ejemplo 3: Hacer que la IA consulte simultaneamente las guias de pagina y botones <a class="header-anchor" href="#_6-3-ejemplo-3-hacer-que-la-ia-consulte-simultaneamente-las-guias-de-pagina-y-botones" aria-label="Permalink to “6.3 Ejemplo 3: Hacer que la IA consulte simultaneamente las guias de pagina y botones”">​</a></h3><p>Tambien puedes pegar dos frases originales a la vez, dejando que la IA consulte simultaneamente la pagina y los botones:</p><blockquote><p>Apple: <a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">&quot;Establish a clear visual hierarchy...&quot;</a></p><p>Fluent: <a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">&quot;Only use one primary button in a layout...&quot;</a></p></blockquote><p>Luego escribe directamente asi:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Consulta las siguientes dos frases de guias de diseno originales:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Apple: &quot;Establish a clear visual hierarchy...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Fluent: &quot;Only use one primary button in a layout...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Ayudame a disenar una pagina de detalles de proyecto.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">La pagina incluye introduccion del proyecto, miembros, actividad reciente y entrada de configuracion.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Jerarquia de pagina mas clara, solo un boton principal, otros botones mas debiles.</span></span></code></pre></div><p>Este metodo es especialmente adecuado para principiantes, porque solo necesitas saber copiar el texto original y agregar un par de frases con tus necesidades.</p><h2 id="_7-como-usar-ia-consultando-las-guias-de-botones-para-generar-directamente-el-diseno-de-botones" tabindex="-1">7. Como usar IA consultando las guias de botones para generar directamente el diseno de botones <a class="header-anchor" href="#_7-como-usar-ia-consultando-las-guias-de-botones-para-generar-directamente-el-diseno-de-botones" aria-label="Permalink to “7. Como usar IA consultando las guias de botones para generar directamente el diseno de botones”">​</a></h2><p>Si solo quieres hacer botones primero, tambien puedes pegar directamente el texto original de la guia de botones.</p><p>Por ejemplo, la definicion de boton de Atlassian es muy corta:</p><blockquote><p><a href="https://atlassian.design/components/button/" target="_blank" rel="noreferrer">&quot;A button triggers an event or action.&quot;</a></p></blockquote><p>Puedes preguntar a la IA asi:</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Consulta esta frase de Atlassian:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;A button triggers an event or action.&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Ayudame a disenar un conjunto de estilos de botones para paginas de backend.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Necesito boton principal, boton secundario, boton de eliminar, y dime donde se usa cada uno.</span></span></code></pre></div><p>Este tipo de prompt es especialmente adecuado para principiantes, basicamente es &quot;pegar texto original + decir necesidades&quot;.</p><h2 id="_8-resumen" tabindex="-1">8. Resumen <a class="header-anchor" href="#_8-resumen" aria-label="Permalink to “8. Resumen”">​</a></h2><p>Consultar guias de diseno de UI para disenar paginas y botones, lo mas importante no es &quot;hacer que se parezca a alguien&quot;, sino aprender estas cosas:</p><ol><li>Usar jerarquia para organizar paginas, en lugar de apilar contenido</li><li>Usar clasificacion de botones para expresar prioridad de operaciones, en lugar de hacer que todos los botones sean igual de llamativos</li><li>Usar las definiciones, limites y criterios de juicio de las guias de diseno para guiar el diseno</li><li>Cuando la IA consulta las guias de otros, consulta &quot;principios y estructura&quot;, no solo el aspecto</li></ol><p>Cuando uses las guias de esta manera, lo que consultes no sera solo un estilo, sino un conjunto de pensamiento de diseno maduro.</p><hr><h2 id="referencias" tabindex="-1">Referencias <a class="header-anchor" href="#referencias" aria-label="Permalink to “Referencias”">​</a></h2><p>Los siguientes enlaces provienen todos de sistemas de diseno oficiales o documentacion oficial:</p><ul><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/" target="_blank" rel="noreferrer">Overview</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/menus" target="_blank" rel="noreferrer">Menus</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/alerts" target="_blank" rel="noreferrer">Alerts</a></li><li>Apple Human Interface Guidelines: <a href="https://developer.apple.com/design/human-interface-guidelines/buttons" target="_blank" rel="noreferrer">Buttons</a></li><li>Apple Archive: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/HowMenusWork.html" target="_blank" rel="noreferrer">How Menus Work</a></li><li>Apple Archive: <a href="https://developer.apple.com/library/archive/documentation/Cocoa/Conceptual/MenuList/Articles/ManagingPopUpItems.html" target="_blank" rel="noreferrer">Managing Pop-Up Buttons and Pull-Down Lists</a></li><li>Material Design: <a href="https://m3.material.io/components/buttons/overview" target="_blank" rel="noreferrer">Buttons overview</a></li><li>Material Design: <a href="https://m1.material.io/components/menus.html" target="_blank" rel="noreferrer">Menus</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/get-started/design" target="_blank" rel="noreferrer">Start designing</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/components/web/react/core/menu/usage" target="_blank" rel="noreferrer">Menu usage</a></li><li>Microsoft Fluent 2: <a href="https://fluent2.microsoft.design/components/web/react/core/button/usage" target="_blank" rel="noreferrer">Button usage</a></li><li>Atlassian Design System: <a href="https://atlassian.design/foundations/" target="_blank" rel="noreferrer">Foundations</a></li><li>Atlassian Design System: <a href="https://atlassian.design/components/button/" target="_blank" rel="noreferrer">Button</a></li></ul>`,146)])])}const g=a(i,[["render",t]]);export{m as __pageData,g as default};
